package dev.kelmagic.client;
import dev.kelmagic.*;import dev.kelmagic.research.*;import net.minecraft.client.*;import net.minecraft.client.gui.screens.*;import net.minecraft.client.gui.components.Button;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.item.*;import net.minecraft.world.level.GameType;import net.minecraft.world.InteractionHand;import net.minecraft.core.BlockPos;import net.neoforged.api.distmarker.Dist;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.bus.api.SubscribeEvent;
/** Developer-only native renderer/input/network fixture. Excluded from release JAR. */
@EventBusSubscriber(modid=KelMagic.MODID,value=Dist.CLIENT)public final class QaResearch {
 static final String[] NAMES={"welcome","words","origins","materials-preview","hypothesis-zero","hypothesis-one","hypothesis-two","thoughts-chat","learned-map","discovery-book","sound","equipment","writing","sealed-great","narrow-materials","narrow-words","narrow-player-book"};
 static int stage,frames,wait,spreads;static boolean opened,requested;static volatile boolean prepared,finished;static Screen old;
 @SubscribeEvent public static void tick(net.neoforged.neoforge.client.event.ClientTickEvent.Post e){if(!Boolean.getBoolean("kelmagic.researchQA116")||stage>17)return;var mc=Minecraft.getInstance();if(stage==17){if(finished){stage=18;System.out.println("RESEARCH_NATIVE_QA_116_COMPLETE");mc.stop();}return;}if(mc.level==null){if(!opened&&mc.screen instanceof TitleScreen&&++wait>35){opened=true;mc.createWorldOpenFlows().openWorld("KelMagicResearch116",()->{});}return;}if(mc.player==null||mc.getSingleplayerServer()==null)return;if(!requested){old=mc.screen;requested=true;prepared=false;final int at=stage;mc.getSingleplayerServer().execute(()->{prepare(mc.getSingleplayerServer().getPlayerList().getPlayers().getFirst(),at);prepared=true;});return;}if(!prepared||mc.screen==old)return;
 if(++frames==4){try{int scale=stage>=14?3:2;if(stage==14)mc.getWindow().setWindowed(960,720);mc.options.guiScale().set(scale);mc.resizeDisplay();if(!(mc.screen instanceof CodexScreen))throw new IllegalStateException("fresh codex screen expected");var screen=(CodexScreen)mc.screen;int section=switch(stage){case 0->7;case 1,15->0;case 2->1;case 10,16->3;case 11->4;case 12->5;case 13->6;default->2;};screen.selectSection(section);if(stage==1||stage==15){var f=CodexScreen.class.getDeclaredField("page");f.setAccessible(true);f.setInt(screen,java.util.List.copyOf(dev.kelmagic.core.KelLexicon.WORDS.keySet()).indexOf("mina"));screen.researchChanged();}if(stage==3){int before=(int)read(screen,"panX");float scaleUi=(float)read(screen,"uiScale");int x=(int)read(screen,"x"),y=(int)read(screen,"y");screen.mouseClicked((x+30)*scaleUi,(y+30)*scaleUi,0);screen.mouseDragged((x+39)*scaleUi,(y+30)*scaleUi,0,9*scaleUi,0);screen.mouseReleased((x+39)*scaleUi,(y+30)*scaleUi,0);if((int)read(screen,"panX")!=(int)before+9)throw new IllegalStateException("map drag failed");set(screen,"panX",(int)before);clickNode(screen,"golden_thread");}if(stage==4||stage==5||stage==6||stage==9||stage==16){clickNode(screen,stage==16?"cassette_player":"golden_thread");if(!(mc.screen instanceof ResearchEntryScreen))throw new IllegalStateException("book popup failed");if(stage==9||stage==16){var method=ResearchEntryScreen.class.getDeclaredMethod("totalSpreads");method.setAccessible(true);spreads=(int)method.invoke(mc.screen);if(spreads<2)throw new IllegalStateException("book requires multiple spreads");}}if(stage==7)mc.setScreen(new ChatScreen(""));if(stage!=7)mc.getToasts().clear();}catch(Exception ex){throw new IllegalStateException(ex);}}
 if(frames==40)capture(mc,NAMES[stage]+(stage==9||stage==16?"-00":""));if(stage==3&&frames==65)capture(mc,"materials-animation-later");
 if((stage==9||stage==16)&&frames>=60&&(frames-60)%20==0){int current=(int)read(mc.screen,"spread");if(current<spreads-1)clickButton(mc.screen,"›");}
 if((stage==9||stage==16)&&frames>=70&&(frames-70)%20==0)capture(mc,(stage==9?"discovery-book-":"player-book-")+String.format("%02d",(int)read(mc.screen,"spread")));
 int limit=stage==3?75:(stage==9||stage==16)?60+spreads*20:55;if(frames>=limit){frames=0;requested=false;if(++stage==17)mc.getSingleplayerServer().execute(()->{reset(mc.getSingleplayerServer().getPlayerList().getPlayers().getFirst());finished=true;});}}
 static Object read(Object s,String name){try{var f=s.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(s);}catch(Exception e){throw new IllegalStateException(e);}}
 static void set(Object s,String name,Object value){try{var f=s.getClass().getDeclaredField(name);f.setAccessible(true);f.set(s,value);}catch(Exception e){throw new IllegalStateException(e);}}
 static void clickNode(CodexScreen screen,String id){try{var n=ResearchCatalog.BY_ID.get(id);var fx=CodexScreen.class.getDeclaredMethod("nx",ResearchCatalog.Node.class);var fy=CodexScreen.class.getDeclaredMethod("ny",ResearchCatalog.Node.class);fx.setAccessible(true);fy.setAccessible(true);float scale=(float)read(screen,"uiScale");if(!screen.mouseClicked((int)fx.invoke(screen,n)*scale,(int)fy.invoke(screen,n)*scale,0))throw new IllegalStateException("native node click failed");}catch(Exception e){throw new IllegalStateException(e);}}
 static void clickButton(Screen screen,String label){var b=screen.children().stream().filter(v->v instanceof Button a&&a.getMessage().getString().equals(label)).map(v->(Button)v).findFirst().orElseThrow();float scale=(float)read(screen,"uiScale");if(!screen.mouseClicked((b.getX()+4)*scale,(b.getY()+4)*scale,0))throw new IllegalStateException("page button failed");}
 static void capture(Minecraft mc,String name){var dir=new java.io.File("/data/native-research-1.16");dir.mkdirs();Screenshot.grab(dir,name+".png",mc.getMainRenderTarget(),m->{});System.out.println("RESEARCH_NATIVE_116_"+name);}
 static void craft(ServerPlayer p,Item output,ItemStack... inputs){var menu=new net.minecraft.world.inventory.CraftingMenu(88,p.getInventory(),net.minecraft.world.inventory.ContainerLevelAccess.create(p.serverLevel(),p.blockPosition()));p.containerMenu=menu;for(int i=0;i<9;i++)menu.getSlot(i+1).set(i<inputs.length?inputs[i]:ItemStack.EMPTY);menu.slotsChanged(menu.getSlot(1).container);if(!menu.getSlot(0).getItem().is(output)||menu.quickMoveStack(p,0).isEmpty())throw new IllegalStateException("real craft fixture failed");p.containerMenu=p.inventoryMenu;p.inventoryMenu.broadcastChanges();}
 static void prepare(ServerPlayer p,int at){if(at==0){p.setGameMode(GameType.SURVIVAL);p.getInventory().clearContent();p.setData(dev.kelmagic.server.MagicAttachments.RESEARCH,ResearchState.EMPTY);p.getInventory().setItem(0,MagicArchive.CODEX.toStack());p.getInventory().setItem(1,new ItemStack(Items.PAPER,32));p.getInventory().setItem(2,new ItemStack(Items.STRING,16));p.getInventory().setItem(3,new ItemStack(Items.GOLD_INGOT,8));p.setHealth(20);p.connection.teleport(42,-60,-12,0,0);p.serverLevel().setBlockAndUpdate(new BlockPos(42,-60,-9),MagicStudy.TABLE.get().defaultBlockState());}
 if(at==1){var old=p.getMainHandItem();p.setItemInHand(InteractionHand.MAIN_HAND,MagicArchive.ANCIENT.toStack());MagicArchive.ANCIENT.get().use(p.serverLevel(),p,InteractionHand.MAIN_HAND);p.setItemInHand(InteractionHand.MAIN_HAND,old);var words=new java.util.ArrayList<>(MagicCopper.WORDS.subList(0,20));for(String word:new String[]{"mina","no","pir"})if(!words.contains(word))words.add(word);old.set(MagicComponents.CODEX_WORDS.get(),java.util.List.copyOf(words));}
 if(at==3)Research.crafted(new net.neoforged.neoforge.event.entity.player.PlayerEvent.ItemCraftedEvent(p,MagicContent.MANA_CORE.toStack(),new net.minecraft.world.SimpleContainer(9)));
 if(at==4){if(!Research.state(p).started().contains("golden_thread")||p.getInventory().getItem(1).getCount()!=31)throw new IllegalStateException("one click creates one paper over network");}
 if(at==5){p.getInventory().getItem(2).shrink(4);craft(p,Items.WHITE_WOOL,Items.STRING.getDefaultInstance(),Items.STRING.getDefaultInstance(),ItemStack.EMPTY,Items.STRING.getDefaultInstance(),Items.STRING.getDefaultInstance());if(Research.progress(Research.state(p),ResearchCatalog.BY_ID.get("golden_thread"))!=1)throw new IllegalStateException("native wool step failed");}
 if(at==6){p.getInventory().getItem(3).shrink(1);craft(p,Items.GOLD_NUGGET,Items.GOLD_INGOT.getDefaultInstance());if(Research.progress(Research.state(p),ResearchCatalog.BY_ID.get("golden_thread"))!=2)throw new IllegalStateException("native nugget step failed");}
 if(at==7){p.connection.teleport(42,-60,-10,0,0);if(!Research.advanceMaterialsAtTable(p))throw new IllegalStateException("automatic sample step failed");p.connection.teleport(42,-60,-12,0,0);}
 if(at==8){var discovery=p.getInventory().items.stream().filter(s->s.is(Research.DISCOVERY)).findFirst().orElseThrow();if(!Research.apply(p,discovery))throw new IllegalStateException("native discovery read failed");}
 if(at==10){Research.grant(p,"magic_ingot");Research.grant(p,"scripter");Research.grant(p,"cassette");}
 if(at==11){Research.grant(p,"magic_cloth");Research.grant(p,"arcane_helmet");}
 if(at==13)Research.tab(p,"great");if(at==16)Research.grant(p,"cassette_player");MagicArchive.CODEX.get().use(p.serverLevel(),p,InteractionHand.MAIN_HAND);p.inventoryMenu.broadcastChanges();}
 static void reset(ServerPlayer p){p.setData(dev.kelmagic.server.MagicAttachments.RESEARCH,ResearchState.EMPTY);p.setGameMode(GameType.SURVIVAL);p.getInventory().clearContent();var b=MagicArchive.CODEX.toStack();var words=new java.util.ArrayList<>(MagicCopper.WORDS.subList(0,20));for(String word:new String[]{"mina","no","pir"})if(!words.contains(word))words.add(word);b.set(MagicComponents.CODEX_WORDS.get(),java.util.List.copyOf(words));p.getInventory().setItem(0,b);int i=1;for(Item item:new Item[]{Items.PAPER,Items.STRING,Items.GOLD_INGOT,Items.IRON_INGOT,Items.LEATHER,Items.REDSTONE,Items.DIAMOND,Items.LAPIS_LAZULI,Items.COPPER_BLOCK,Items.BOOK,Items.FEATHER,Items.INK_SAC,Items.GLASS_BOTTLE,Items.OAK_LOG,Items.COBBLESTONE,Items.WHITE_WOOL})p.getInventory().setItem(i++,new ItemStack(item,64));p.getInventory().setItem(i++,MagicArchive.ANCIENT.toStack());p.getInventory().setItem(i++,MagicContent.SCRIPTER.toStack());p.setHealth(20);p.setData(dev.kelmagic.server.MagicAttachments.MANA,new dev.kelmagic.server.MagicAttachments.Mana(5,false));p.setData(dev.kelmagic.server.MagicAttachments.ARCANE_BURN,0);p.getAbilities().flying=false;p.onUpdateAbilities();p.connection.teleport(42,-60,-12,0,0);p.inventoryMenu.broadcastChanges();}
 private QaResearch(){}
}
